#!/usr/bin/env bash
set -Eeuo pipefail

cd /workspaces/Photon-Camera

EXPECTED_BRANCH="experimental-effective-stack"
EXPECTED_HEAD="cedc3ab3e39ad49d42523cff7e3711f8baa69a13"
EXPECTED_BUILD="26171"
NEW_BUILD="26172"
NEW_VERSION="0.9726172"

STAMP="$(date +%Y%m%d_%H%M%S)"
OUT="/workspaces/Photon-Camera/build_${NEW_BUILD}_motion_local_contribution_${STAMP}"
BACKUP_BRANCH="backup-before-motion-local-contribution-${NEW_BUILD}-${STAMP}"

PYRAMID="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/scripts/PyramidMerging.java"
HDRX="app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java"
PARAMS="app/src/main/java/com/particlesdevs/photoncamera/processing/render/Parameters.java"
NOISE="app/src/main/java/com/particlesdevs/photoncamera/processing/render/NoiseModeler.java"
POST="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java"
MERGE_SHADER="app/src/main/assets/shaders/merge/merge11.glsl"
MOTION_MERGE_SHADER="app/src/main/assets/shaders/merge/motionmerge11.glsl"
CONTRIBUTION_INIT_SHADER="app/src/main/assets/shaders/merge/contributioninit.glsl"
VERSION="app/version.properties"

CAPTURE="app/src/main/java/com/particlesdevs/photoncamera/capture/CaptureController.java"
AUTO_EXPOSURE="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/AutoExposure.java"
CAPTURE_SHARP="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/CaptureSharpening.java"
ESD_JAVA="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/ESD3D2.java"
ESD_SHADER="app/src/main/assets/shaders/denoise/esd3d2.glsl"
INITIAL="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/Initial.java"
COLOR_SHADER="app/src/main/assets/shaders/initial.glsl"
FINAL_SHARP="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/Sharpen2.java"
REGISTRY="app/src/main/java/com/particlesdevs/photoncamera/settings/TunableRegistry.java"
LUMA_JAVA="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionLumaDenoise.java"
LUMA_SHADER="app/src/main/assets/shaders/denoise/motionlumadenoise.glsl"
CHROMA_JAVA="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionChromaDenoise.java"
CHROMA_SHADER="app/src/main/assets/shaders/denoise/motionchromadenoise.glsl"
EXPOSURE_SELECTOR="app/src/main/java/com/particlesdevs/photoncamera/processing/parameters/IsoExpoSelector.java"
TUNABLE_GENERATOR="app/src/main/java/com/particlesdevs/photoncamera/settings/TunablePreferenceGenerator.java"
TUNABLE_INJECTOR="app/src/main/java/com/particlesdevs/photoncamera/settings/TunableInjector.java"
TUNABLE_ANNOTATION="app/src/main/java/com/particlesdevs/photoncamera/settings/annotations/Tunable.java"
TUNABLE_SEEKBAR="app/src/main/java/com/particlesdevs/photoncamera/ui/settings/custompreferences/TunableSeekBarPreference.java"

fail() {
    echo
    echo "============================================================"
    echo " BUILD FAILED"
    echo " Reason: $1"
    echo " Workspace: $OUT"
    echo "============================================================"
    exit "${2:-1}"
}

trap 'code=$?; if [ "$code" -ne 0 ]; then echo; echo "FAILED: build 26172 (exit $code)"; echo "Workspace: $OUT"; fi' EXIT

check_expected_hash() {
    local file="$1"
    shift
    local actual
    actual="$(sha256sum "$file" | awk '{print $1}')"

    for expected in "$@"; do
        if [ "$actual" = "$expected" ]; then
            echo "PASS source hash: $file"
            return 0
        fi
    done

    echo "Unexpected source hash: $file"
    echo "Actual: $actual"
    return 1
}

echo "============================================================"
echo " PhotonCamera $NEW_VERSION"
echo " Motion Bayer contribution measurement and recovery"
echo "============================================================"

[ "$(git branch --show-current)" = "$EXPECTED_BRANCH" ]     || fail "Expected branch $EXPECTED_BRANCH"

[ "$(git rev-parse HEAD)" = "$EXPECTED_HEAD" ]     || fail "Expected HEAD $EXPECTED_HEAD"

grep -q "^VERSION_BUILD=${EXPECTED_BUILD}$" "$VERSION"     || fail "Expected VERSION_BUILD=${EXPECTED_BUILD}"

EXPECTED_MODIFIED="$ESD_SHADER
$MERGE_SHADER
$CAPTURE
$AUTO_EXPOSURE
$CAPTURE_SHARP
$ESD_JAVA
$INITIAL
$POST
$FINAL_SHARP
$PYRAMID
$HDRX
$PARAMS
$REGISTRY
$VERSION"

ACTUAL_MODIFIED="$(git status --short --untracked-files=no | awk '{print $2}' | sort)"
EXPECTED_SORTED="$(printf '%s\n' "$EXPECTED_MODIFIED" | sort)"

[ "$ACTUAL_MODIFIED" = "$EXPECTED_SORTED" ]     || {
        echo "Expected tracked state:"
        printf '%s\n' "$EXPECTED_SORTED"
        echo
        echo "Actual tracked state:"
        printf '%s\n' "$ACTUAL_MODIFIED"
        fail "Workspace does not match the audited 26171 state"
    }

for file in "$LUMA_JAVA" "$LUMA_SHADER" "$CHROMA_JAVA" "$CHROMA_SHADER"; do
    [ -f "$file" ] || fail "Required 26171 Motion source missing: $file"
done

[ ! -e "$MOTION_MERGE_SHADER" ]     || fail "$MOTION_MERGE_SHADER already exists"

[ ! -e "$CONTRIBUTION_INIT_SHADER" ]     || fail "$CONTRIBUTION_INIT_SHADER already exists"

grep -Fq 'MOTION_26168_MERGE_NOISE_AWARE' "$PYRAMID"     || fail "26168 merge correction missing"

grep -Fq 'MOTION_26171_ESD3D2_TUNABLE' "$ESD_JAVA"     || fail "26171 ESD tuning missing"

grep -Fq 'MOTION_26171_LUMA_TUNABLE' "$LUMA_JAVA"     || fail "26171 luma tuning missing"

grep -Fq 'MOTION_26171_CHROMA_TUNABLE' "$CHROMA_JAVA"     || fail "26171 chroma tuning missing"

grep -Fq 'MOTION_26171_TONE_TUNABLE' "$AUTO_EXPOSURE"     || fail "26171 tone tuning missing"

grep -Fq 'MOTION_26171_CAPTURE_SHARPEN_TUNABLE' "$CAPTURE_SHARP"     || fail "26171 capture sharpening missing"

grep -Fq 'MOTION_26171_FINAL_SHARPEN_TUNABLE' "$FINAL_SHARP"     || fail "26171 final sharpening missing"

grep -Fq 'MOTION_26166_BLACK_LEVEL_SELECTED' "$CAPTURE"     || fail "Validated Motion black-level path missing"

grep -Fq 'MOTION_26165_HOMOGENEOUS_RAW_STACK' "$CAPTURE"     || fail "Twenty-frame Motion stack marker missing"

grep -Fq 'MOTION_26166_IMAGE_SAVED_COMPLETE' "$HDRX"     || fail "Image-save completion path missing"

grep -Fq 'pRGB = corr*sensorToIntermediate*(pRGB*neutralPoint);' "$COLOR_SHADER"     || fail "Original Photon color path missing"

grep -Fq 'PyramidMerging.class' "$REGISTRY"     || fail "PyramidMerging is not registered for tunables"

grep -Fq 'PostPipeline.class' "$REGISTRY"     || fail "PostPipeline is not registered for tunables"

grep -Fq 'showPreciseValueDialog' "$TUNABLE_SEEKBAR"     || fail "Precise numeric-entry tuning UI missing"

grep -Fq 'setNeutralButton("Reset"' "$TUNABLE_SEEKBAR"     || fail "Per-setting Reset control missing"

! grep -Rqs 'MOTION_26172_'     "$PYRAMID" "$HDRX" "$PARAMS" "$NOISE" "$POST"     "$MERGE_SHADER"     || fail "26172 source appears partially applied"

echo
echo "=== VERIFY EXACT AUDITED SOURCE ==="
check_expected_hash 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/scripts/PyramidMerging.java' 0334cf31c8e4ae67e4b1250fc827ea851cacf6a8c37208a23340e831412b2153 367f40444d5bb566078e1cdac921516666a4927c3523b19abdb9ebdc08f52522 5e2204316c38146f9ea1b91504a5a00560a427057efa6b27ad9dcdd533d2207a
check_expected_hash 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java' bfe49de53053bd3d93f28de9c013befbf7822dbb1a6755b548b30a0aa759fcf0 ebfb8e60a30cf4d5000a566b680df7dc07edac5d7cf388f099c15ffc87c69f2a f7dec65cd8a0310856bb8055db2f1140ec15d44b3455edefc7b9c14c2307fab8
check_expected_hash 'app/src/main/java/com/particlesdevs/photoncamera/processing/render/Parameters.java' 2a0289a24648fffa482f3862e69cebce58e801cd437d4048be9a732c5ab500c0 4dfb782ae2e6cfb1c233a4eb6302aa2db913324ccf5dc66d9d3da8aa8dfab440 803485b62e5c75b24e6c7c13ee299bb9b8ffa314b967e3b5dcd30e9982a1add4
check_expected_hash 'app/src/main/java/com/particlesdevs/photoncamera/processing/render/NoiseModeler.java' 44418345380cd29532a2f5b463dbdcf7d2a71edfefc8b1e48594b31ce8c31955 75020e63e42951595c76bdf067b58d40189016d670fafe0f602de0f1274e2b48 a1d82ae70620c6380f7d7efb9c26047bd494ab32901966f6050d435e96ae7678
check_expected_hash 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java' 247073daf3f3266d9ebff4af8798ad729243fb344d64f402024cc7d4721734c0 28fb7c2ca97330ba3631238cb55d2011e5528e7fe8af4686e9528b374e5789b0 f43cdea590ceb2e44af7c4bc4f99e913fd26d81cef6d9921e3b7eb63bea20c66
check_expected_hash 'app/src/main/assets/shaders/merge/merge11.glsl' 40f343da0719a256a6a55ac485412e49e4aca876d9374703c13b396a359710e8 70c59c205bafcb9fe5764cd56d3ed9a3e493f5007cc804334d9178293b8f1926 c67894455019a4dc0298235cf1e7ecc5a4fd6f78973c85c581473166cce3c99b || fail "One or more target sources changed after the audit"

mkdir -p "$OUT/source_before" "$OUT/source_after"

echo
echo "=== CREATE BACKUP BRANCH AND COMPLETE PATCH ==="

git branch "$BACKUP_BRANCH" HEAD

{
    git diff --binary HEAD
    git diff --binary --no-index /dev/null "$LUMA_JAVA" || true
    git diff --binary --no-index /dev/null "$LUMA_SHADER" || true
    git diff --binary --no-index /dev/null "$CHROMA_JAVA" || true
    git diff --binary --no-index /dev/null "$CHROMA_SHADER" || true
} > "$OUT/working-tree-before-${NEW_BUILD}.patch"

for file in     "$PYRAMID" "$HDRX" "$PARAMS" "$NOISE" "$POST"     "$MERGE_SHADER" "$VERSION"; do
    cp "$file" "$OUT/source_before/$(basename "$file")"
done

sha256sum     "$CAPTURE" "$AUTO_EXPOSURE" "$CAPTURE_SHARP"     "$ESD_JAVA" "$ESD_SHADER" "$INITIAL" "$COLOR_SHADER"     "$FINAL_SHARP" "$REGISTRY"     "$LUMA_JAVA" "$LUMA_SHADER" "$CHROMA_JAVA" "$CHROMA_SHADER"     "$EXPOSURE_SELECTOR"     "$TUNABLE_GENERATOR" "$TUNABLE_INJECTOR"     "$TUNABLE_ANNOTATION" "$TUNABLE_SEEKBAR"     "$MERGE_SHADER"     > "$OUT/protected-before.sha256"

echo "Backup branch: $BACKUP_BRANCH"
echo "Backup patch:  $OUT/working-tree-before-${NEW_BUILD}.patch"

echo
echo "=== APPLY 26172 MOTION-ONLY MERGE IMPLEMENTATION ==="

mkdir -p "$(dirname 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/scripts/PyramidMerging.java')"
base64 -d > 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/scripts/PyramidMerging.java' <<'PAYLOAD_0_EOF'

PAYLOAD_0_EOF

mkdir -p "$(dirname 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java')"
base64 -d > 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java' <<'PAYLOAD_1_EOF'

PAYLOAD_1_EOF

mkdir -p "$(dirname 'app/src/main/java/com/particlesdevs/photoncamera/processing/render/Parameters.java')"
base64 -d > 'app/src/main/java/com/particlesdevs/photoncamera/processing/render/Parameters.java' <<'PAYLOAD_2_EOF'

PAYLOAD_2_EOF

mkdir -p "$(dirname 'app/src/main/java/com/particlesdevs/photoncamera/processing/render/NoiseModeler.java')"
base64 -d > 'app/src/main/java/com/particlesdevs/photoncamera/processing/render/NoiseModeler.java' <<'PAYLOAD_3_EOF'

PAYLOAD_3_EOF

mkdir -p "$(dirname 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java')"
base64 -d > 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java' <<'PAYLOAD_4_EOF'

PAYLOAD_4_EOF

mkdir -p "$(dirname 'app/src/main/assets/shaders/merge/motionmerge11.glsl')"
base64 -d > 'app/src/main/assets/shaders/merge/motionmerge11.glsl' <<'PAYLOAD_5_EOF'

PAYLOAD_5_EOF

mkdir -p "$(dirname 'app/src/main/assets/shaders/merge/contributioninit.glsl')"
base64 -d > 'app/src/main/assets/shaders/merge/contributioninit.glsl' <<'PAYLOAD_6_EOF'

PAYLOAD_6_EOF

python3 - <<'PY'
from pathlib import Path

version_path = Path("app/version.properties")
text = version_path.read_text()

if text.count("VERSION_BUILD=26171") != 1:
    raise SystemExit(
        "ERROR: VERSION_BUILD=26171 expected exactly once"
    )

version_path.write_text(
    text.replace(
        "VERSION_BUILD=26171",
        "VERSION_BUILD=26172",
        1,
    )
)
PY

echo
echo "=== VERIFY 26172 IMPLEMENTATION ==="

grep -Fq 'MOTION_26172_CONTRIBUTION_TRACKING' "$PYRAMID"     || fail "Contribution tracking marker missing"

grep -Fq 'MOTION_26172_LOCAL_CONTRIBUTION' "$PYRAMID"     || fail "Contribution percentile marker missing"

grep -Fq 'merge/motionmerge11' "$PYRAMID"     || fail "Motion-isolated merge shader routing missing"

grep -Fq 'merge/merge11' "$PYRAMID"     || fail "Original Photo/Night merge routing missing"

grep -Fq 'motionNoiseDifferenceRecovery = 0.75f' "$PYRAMID"     || fail "Motion merge recovery default missing"

grep -Fq 'motionEffectiveStackPercentile = 0.25f' "$PYRAMID"     || fail "Measured-stack percentile default missing"

grep -Fq 'MOTION_26172_LOCAL_STACK_MODEL' "$HDRX"     || fail "Measured model handoff missing"

grep -Fq 'dngNoiseModelSelectedBeforeSave=true' "$HDRX"     || fail "DNG pre-save model marker missing"

python3 - <<'PY'
from pathlib import Path

text = Path(
    "app/src/main/java/com/particlesdevs/photoncamera/"
    "processing/processor/HdrxProcessor.java"
).read_text()

model = text.find("MOTION_26172_LOCAL_STACK_MODEL")
save = text.find("ImageSaver.Util.saveStackedRaw")

if model < 0 or save < 0 or model > save:
    raise SystemExit(
        "ERROR: measured stack model must be selected before DNG save"
    )
PY

grep -Fq 'localContributionMeasured = false' "$PARAMS"     || fail "Parameters contribution state missing"

grep -Fq '"\\n EffectiveFrameCount="' "$PARAMS"     || fail "Effective frame metadata missing"

grep -Fq 'computeStackingNoiseModel(float frameCount)' "$NOISE"     || fail "Fractional effective-frame noise model missing"

grep -Fq 'MOTION_26172_STACKING_NOISE_MODEL' "$NOISE"     || fail "Noise model marker missing"

grep -Fq 'motionMeasuredResidualVarianceBoost = 0.0f' "$POST"     || fail "Measured residual double-count protection missing"

grep -Fq 'MOTION_26172_LOCAL_NOISE_HANDOFF' "$POST"     || fail "Post-pipeline measured noise marker missing"

grep -Fq 'layout(r16f, binding = 4)' "$MOTION_MERGE_SHADER"     || fail "Motion contribution image binding missing"

grep -Fq 'preservedIndependentFraction' "$MOTION_MERGE_SHADER"     || fail "Independent contribution measurement missing"

grep -Fq 'motionNoiseRecoveryStrength' "$MOTION_MERGE_SHADER"     || fail "Noise-consistent difference recovery missing"

grep -Fq 'layout(r16f, binding = 0)' "$CONTRIBUTION_INIT_SHADER"     || fail "Contribution initializer missing"

grep -q '^VERSION_BUILD=26172$' "$VERSION"     || fail "VERSION_BUILD was not updated"

sha256sum -c "$OUT/protected-before.sha256"     || fail "A protected 26171 file changed"

git diff --check     || fail "git diff --check reported a formatting problem"

if git diff | grep -E     '^[+-].*(mIsRecordingVideo|CameraMode\.RAWVIDEO|TEMPLATE_RECORD|MediaRecorder|CONTROL_AF_MODE_CONTINUOUS_VIDEO|getSelectedFpsRange)'; then
    fail "Video or RAW Video behavior changed unexpectedly"
fi

grep -Fq '@Tunable(title = "Enable Adaptive Noise Model"' "$PYRAMID"     || fail "Adaptive Noise Model setting was removed"

for file in     "$PYRAMID" "$HDRX" "$PARAMS" "$NOISE" "$POST"     "$MOTION_MERGE_SHADER" "$CONTRIBUTION_INIT_SHADER" "$VERSION"; do
    cp "$file" "$OUT/source_after/$(basename "$file")"
done

git diff --stat | tee "$OUT/change-summary-tracked.txt"

{
    git diff --binary HEAD
    git diff --binary --no-index /dev/null "$LUMA_JAVA" || true
    git diff --binary --no-index /dev/null "$LUMA_SHADER" || true
    git diff --binary --no-index /dev/null "$CHROMA_JAVA" || true
    git diff --binary --no-index /dev/null "$CHROMA_SHADER" || true
    git diff --binary --no-index /dev/null "$MOTION_MERGE_SHADER" || true
    git diff --binary --no-index /dev/null "$CONTRIBUTION_INIT_SHADER" || true
} > "$OUT/combined-${NEW_BUILD}-motion-local-contribution.patch"

echo
echo "PASS: Motion now uses an isolated merge shader."
echo "PASS: Photo and Night retain the existing merge11 shader."
echo "PASS: noise-consistent alternate differences are recovered before averaging."
echo "PASS: local independent contribution is measured at Bayer-quad resolution."
echo "PASS: p10/p25/p50/p75/p90 and low-contribution fractions are logged."
echo "PASS: measured effective frames update the DNG noise model before RAW save."
echo "PASS: the same measured count drives the JPEG noise model."
echo "PASS: the old fixed residual boost is not double-counted when measurement succeeds."
echo "PASS: all 20 retained captures remain available."
echo "PASS: 26171 tuning, tone, sharpening, color and black-level paths are preserved."
echo "PASS: Video and RAW Video remain isolated."
echo "PASS: Adaptive Noise Model setting is unchanged; leave it OFF."

echo
echo "=== BUILDING PHOTONCAMERA $NEW_VERSION ==="
echo "Do not open another terminal until BUILD COMPLETE appears."

set +e
./gradlew clean assembleDebug 2>&1 | tee "$OUT/build-${NEW_BUILD}.log"
BUILD_STATUS=${PIPESTATUS[0]}
set -e

if [ "$BUILD_STATUS" -ne 0 ]; then
    grep -nE         'error:|cannot find symbol|FAILURE:|Compilation failed|What went wrong|Error compiling shader'         "$OUT/build-${NEW_BUILD}.log"         | tail -500         > "$OUT/relevant-errors.txt" || true

    fail "Gradle build failed; inspect $OUT/relevant-errors.txt"         "$BUILD_STATUS"
fi

APK="$(find app/build/outputs/apk/debug -maxdepth 1 -type f -name '*.apk' | head -n 1)"

[ -n "$APK" ] && [ -f "$APK" ]     || fail "Debug APK was not created"

APK_COPY="$OUT/PhotonCamera-${NEW_VERSION}-motion-local-contribution-debug.apk"

cp "$APK" "$APK_COPY"
sha256sum "$APK" "$APK_COPY" | tee "$OUT/sha256.txt"

echo
echo "============================================================"
echo " BUILD COMPLETE"
echo "============================================================"
echo "PhotonCamera:   $NEW_VERSION"
echo "VERSION_BUILD: $NEW_BUILD"
echo "APK:           $APK_COPY"
echo "Backup branch: $BACKUP_BRANCH"
echo "Backup patch:  $OUT/working-tree-before-${NEW_BUILD}.patch"
echo "Combined patch:$OUT/combined-${NEW_BUILD}-motion-local-contribution.patch"
echo "Build log:     $OUT/build-${NEW_BUILD}.log"
echo
echo "Settings:"
echo "  Settings -> Tunable Settings -> Tunable - Motion Noise Tuning"
echo
echo "New defaults:"
echo "  Motion merge noise recovery:       0.75"
echo "  Motion merge recovery gate:        1.50"
echo "  Motion effective-stack percentile: 0.25"
echo "  Motion measured residual boost:    0.00"
echo
echo "Expected log markers:"
echo "  MOTION_26172_CONTRIBUTION_TRACKING"
echo "  MOTION_26172_LOCAL_CONTRIBUTION"
echo "  MOTION_26172_LOCAL_STACK_MODEL"
echo "  MOTION_26172_STACKING_NOISE_MODEL"
echo "  MOTION_26172_LOCAL_NOISE_HANDOFF"
echo "  MOTION_26172_COLOR_AND_STACK_HANDOFF"
echo "  MOTION_26166_IMAGE_SAVED_COMPLETE success=true"
echo
echo "Adaptive Noise Model: leave OFF."
echo
git status --short --untracked-files=no
echo
echo "Safe to open another terminal now."

trap - EXIT
